def strat_evolved_80059(i, d):
    rsi = d["rsi"][i]
    donch_haut = d["donchian_haut"][i]
    donch_bas = d["donchian_bas"][i]
    prix = d["clotures"][i]
    bb_haut = d["bb_haut"][i]
    bb_bas = d["bb_bas"][i]

    if rsi is None:
        return None
    if donch_haut is None:
        return None
    if donch_bas is None:
        return None
    if prix is None:
        return None
    if bb_haut is None:
        return None
    if bb_bas is None:
        return None

    volatilite_bb = bb_haut - bb_bas
    if volatilite_bb is None:
        return None

    # Filtre volatilité: ne trader qu'en régime modéré
    if volatilite_bb <= 0:
        return None
    if volatilite_bb > (prix * 0.08):
        return None

    if rsi < 35 and prix < donch_bas:
        return "ACHAT"

    if rsi > 70 and prix > donch_haut:
        return "VENTE"

    return None
